// `pnpm db:env` — writes .env.local from the running local Supabase, so a clean
// clone never needs keys copied by hand. Local keys only; never commit the file.
import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";

const status = JSON.parse(
  execFileSync("pnpm", ["exec", "supabase", "status", "--output", "json"], {
    encoding: "utf8",
    stdio: ["ignore", "pipe", "inherit"],
  }),
);

const lines = [
  "# Generated by `pnpm db:env` from the local Supabase. Do not commit.",
  `SUPABASE_URL=${status.API_URL}`,
  `SUPABASE_PUBLISHABLE_KEY=${status.PUBLISHABLE_KEY}`,
  `SUPABASE_SECRET_KEY=${status.SECRET_KEY}`,
  `DATABASE_URL=${status.DB_URL}`,
  `MAILPIT_URL=${status.MAILPIT_URL}`,
  `SUPABASE_STUDIO_URL=${status.STUDIO_URL}`,
  "",
];

writeFileSync(".env.local", lines.join("\n"), { mode: 0o600 });
console.log("Wrote .env.local");
